import java.io.*;import java.net.*;import java.net.http.*;import java.nio.file.*;import java.time.*;import java.util.*;
public class Features753Check {
 static String base;static final HttpClient http=HttpClient.newHttpClient();interface Body{void write(DataOutputStream out)throws Exception;}
 static void ok(boolean b,String message){if(!b)throw new AssertionError(message);System.out.println("PASS: "+message);}
 static DataInputStream call(String token,String op,Body writer)throws Exception{var bytes=new ByteArrayOutputStream();var out=new DataOutputStream(bytes);out.writeInt(GunnyServer.MAGIC);out.writeUTF(op);if(writer!=null)writer.write(out);var r=HttpRequest.newBuilder(URI.create(base+"/api")).header("X-Gunny-Bag","1").header("X-Gunny-Equipment","1").header("X-Gunny-Arsenal","2").header("X-Gunny-Client","3");if(token!=null)r.header("Authorization","Bearer "+token);var reply=http.send(r.POST(HttpRequest.BodyPublishers.ofByteArray(bytes.toByteArray())).build(),HttpResponse.BodyHandlers.ofByteArray());var in=new DataInputStream(new ByteArrayInputStream(reply.body()));if(in.readUnsignedByte()!=0)throw new IOException(in.readUTF());return in;}
 static String login(String mail)throws Exception{return call(null,"login",o->{o.writeUTF(mail);o.writeUTF("test-password-123");}).readUTF();}
 static HttpResponse<String> web(String path,Map<String,Object> body,String cookie)throws Exception{var r=HttpRequest.newBuilder(URI.create(base+path));if(cookie!=null)r.header("Cookie",cookie);if(body!=null)r.header("Content-Type","application/json").header("Origin",base).POST(HttpRequest.BodyPublishers.ofString(Json.write(body)));return http.send(r.build(),HttpResponse.BodyHandlers.ofString());}
 static class Records extends Admin750Check.Records {
  final Map<String,Map<String,Object>> grants=new HashMap<>();Records(CloudStore.Memory store)throws Exception{super(store);}
  synchronized Object call(String op,Map<String,Object> d)throws Exception{if(!op.equals("wallet-add"))return super.call(op,d);String key=Json.str(d,"request_key"),id=Json.str(d,"id");int coins=Json.num(d,"coins",0),money=Json.num(d,"money",0);var p=memory.profile(id);if(grants.containsKey(key)){if(!grants.get(key).equals(d))throw new IllegalArgumentException("Invalid request key");}else{if(p.coins+coins>999999||p.shoppingMoney+money>999999)throw new IllegalArgumentException("Wallet limit");p.coins+=coins;p.shoppingMoney+=money;grants.put(key,new HashMap<>(d));accounts.get(id).put("coins",p.coins);accounts.get(id).put("shopping_money",p.shoppingMoney);}return Map.of("coins",p.coins,"money",p.shoppingMoney);}
 }
 public static void main(String[] args)throws Exception{var store=new CloudStore.Memory(true);store.register("a@753.test","test-password-123","A");store.register("b@753.test","test-password-123","B");var records=new Records(store);try(var server=new GunnyServer(new InetSocketAddress("127.0.0.1",args.length>0?8753:0),Path.of("backend/assets"),store,records,Admin750Check.PASSWORD,true)){base="http://127.0.0.1:"+server.port();if(args.length>0){System.out.println("Preview: "+base);new java.util.concurrent.CountDownLatch(1).await();return;}
 String token=login("a@753.test"),other=login("b@753.test");var p=server.sessions.get(token).profile;ok(p.owned==0&&p.wornMask==0&&p.custom&&Arrays.stream(p.wardrobe).sum()==0,"New online account starts bare with empty possessions");for(int kind=0;kind<7;kind++)ok(ShopCatalog.price(kind,0)==0,"First item is free in category "+kind);call(token,"checkout",out->{out.writeByte(0);for(int k=0;k<7;k++)out.writeShort(1);});ok(p.shoppingMoney==0&&p.owned==1&&Arrays.stream(p.wardrobe,0,6).sum()==6&&p.wornMask==0,"Zero-balance player can buy all first items without auto-equipping");call(token,"equip",o->{o.writeByte(2);o.writeByte(0);});call(token,"gender",o->o.writeByte(1));ok(p.wornMask==0&&p.custom,"Gender switch does not equip unowned free clothes");call(token,"gender",o->o.writeByte(0));int[] layout=new int[175];Arrays.fill(layout,-1);layout[24]=0;layout[74]=20;call(token,"baglayout",out->{out.writeShort(175);for(int v:layout)out.writeShort(v);});ok(p.bagLayout[24]==0&&p.bagLayout[74]==20,"Sparse bag positions are stored on the authenticated profile");String again=login("a@753.test");ok(server.sessions.get(again).profile.bagLayout[74]==20,"Bag positions survive another login");boolean rejected=false;try{call(other,"baglayout",out->{out.writeShort(175);for(int v:layout)out.writeShort(v);});}catch(IOException e){rejected=true;}ok(rejected&&store.profile(server.sessions.get(other).id).bagLayout[24]==-1,"One account cannot claim another account's items by layout");
 var auth=web("/admin/api/login",Map.of("password",Admin750Check.PASSWORD),null);String adminCookie=auth.headers().firstValue("Set-Cookie").orElseThrow().split(";")[0];Map<String,Object> grant=Map.of("id",p.id,"coins",2000,"money",100,"reason","Test grant","request_key",UUID.randomUUID().toString());ok(web("/admin/api/wallet-add",grant,null).statusCode()==401,"Wallet changes require administrator authentication");ok(web("/admin/api/wallet-add",grant,adminCookie).statusCode()==200,"Admin can add both currencies");web("/admin/api/wallet-add",grant,adminCookie);ok(p.coins==2000&&p.shoppingMoney==100,"Retrying the identical grant does not add twice");var negative=new HashMap<>(grant);negative.put("coins",-5);ok(web("/admin/api/wallet-add",negative,adminCookie).statusCode()==400,"Negative wallet grant is rejected");var presence=call(again,"presence",null);presence.readInt();ok(presence.readInt()==2000&&presence.readInt()==100,"Online lobby can receive updated admin balances");
 var page=web("/account/",null,null);ok(page.statusCode()==200&&page.body().contains("id=\"login\"")&&!page.body().contains("localhost"),"Player account page retains its separate sign-in form");var signed=web("/auth/api/login",Map.of("email","a@753.test","password","test-password-123"),null);ok(signed.statusCode()==200&&!signed.body().contains("test-password")&&server.sessions.containsKey(again),"Web player sign-in keeps game session and never returns the password");String playerCookie=signed.headers().firstValue("Set-Cookie").orElseThrow().split(";")[0];ok(web("/admin/api/accounts",null,playerCookie).statusCode()==401,"Player web session does not grant admin access");web("/auth/api/logout",Map.of(),playerCookie);ok(web("/auth/api/session",null,playerCookie).statusCode()==401,"Player logout invalidates its cookie");}
 System.out.println("All features 7.5.3 server checks passed");}
}
